package com.company.platform.integration.application;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;
@Component public class IntegrationScheduler{private final IntegrationPlatformService platform;private final SynchronizationEngine engine;public IntegrationScheduler(JdbcTemplate ignored,IntegrationPlatformService p,SynchronizationEngine e){platform=p;engine=e;}@Scheduled(fixedDelayString="${INTEGRATION_SCHEDULER_DELAY_MS:60000}")public void runDueJobs(){}public Map<String,Object> manual(UUID connectorId,String type){return engine.synchronize(connectorId,type,Map.of("trigger",type,"at",Instant.now().toString()));}}
